using System;
using System.IO;
using System.Threading;
using SpatialWallpaper.Blueprint;
class ProcessChecks {
 static int Main(string[] args){string root=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(args[1]),"Validation","Blueprint","worker-check-"+Guid.NewGuid().ToString("N")));try{var first=BlueprintImportProcess.Run(args[0],args[1],File.ReadAllText(args[2]),root,CancellationToken.None);if(first.CacheHit||first.Document.BlockCount!=2090||!first.Compiled.CanApply)throw new Exception("cold worker import");Console.WriteLine("PASS resource-limited-worker-cold-import");var second=BlueprintImportProcess.Run(args[0],args[1],File.ReadAllText(args[2]),root,CancellationToken.None);if(!second.CacheHit||second.Compiled.TriangleCount!=first.Compiled.TriangleCount)throw new Exception("warm worker import");Console.WriteLine("PASS resource-limited-worker-warm-import");if(Directory.GetDirectories(Path.Combine(root,"jobs")).Length!=0)throw new Exception("job files retained");Console.WriteLine("PASS worker-exit-removes-transient-files");var token=new CancellationTokenSource();token.Cancel();bool cancelled=false;try{BlueprintImportProcess.Run(args[0],args[1],File.ReadAllText(args[2]),root,token.Token);}catch(OperationCanceledException){cancelled=true;}if(!cancelled)throw new Exception("worker cancellation");Console.WriteLine("PASS worker-cancellation-cleans-up");string selected=Path.Combine(root,"selected.zip");File.Copy(args[1],selected);var snapshot=BlueprintImportProcess.Run(args[0],selected,File.ReadAllText(args[2]),root,CancellationToken.None);File.WriteAllBytes(selected,new byte[]{1,2,3});File.Delete(selected);var store=new BlueprintWorkspace(root);var saved=store.Create("Preserved source",snapshot.Document.SourceHash,File.ReadAllBytes(snapshot.SourcePath),new BlueprintSettings());var reopened=BlueprintReader.Read(File.ReadAllBytes(store.SourcePath(saved.SourceHash)),"saved.blueprint",CancellationToken.None);if(reopened.SourceHash!=snapshot.Document.SourceHash||reopened.BlockCount!=2090)throw new Exception("mutable original source corrupted saved work");Console.WriteLine("PASS import-snapshot-survives-original-replacement-and-deletion");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
